      IF reset = '1' THEN
        alpha_reg <= (OTHERS => to_signed(16#000#, 9));
      ELSIF enb = '1' THEN
        alpha_reg(0 TO 44) <= data_signed(0 TO 44);
        alpha_reg(45 TO 89) <= alpha_reg(0 TO 44);
      END IF;
    END IF;
  END PROCESS c_process;

