        validD <= '0';
      ELSIF enb = '1' THEN
        validD <= valid;
      END IF;
    END IF;
  END PROCESS c_3_process;


  validDNeg <=  NOT validD;

  intReset <= valid AND validDNeg;

  extReset <= reset_1 OR intReset;

  abs_rsvd_output : PROCESS (dataReg)
    VARIABLE y : signed(9 DOWNTO 0);
    VARIABLE cast : signed(9 DOWNTO 0);
  BEGIN
    y := to_signed(16#000#, 10);
    cast := to_signed(16#000#, 10);

    FOR k IN 0 TO 44 LOOP
      IF dataReg(k) < to_signed(16#000#, 9) THEN 
        cast := resize(dataReg(k), 10);
        y :=  - (cast);
      ELSE 
        y := resize(dataReg(k), 10);
      END IF;
      dataAbs(k) <= unsigned(y(8 DOWNTO 0));
    END LOOP;

  END PROCESS abs_rsvd_output;


  minCalculation_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
